import json
with open('result.txt', 'r') as f:
    content = f.read()
objects = []
stack = 0
start = -1
for i, ch in enumerate(content):
    if ch == '{':
        if stack == 0:
            start = i
        stack += 1
    elif ch == '}':
        stack -= 1
        if stack == 0 and start != -1:
            obj_str = content[start:i+1]
            # quick validation: must contain 'Date'
            if '\"Date\"' in obj_str:
                objects.append(obj_str)
            start = -1
print(f'Found {len(objects)} candidate objects')
parsed = []
for obj in objects:
    try:
        parsed.append(json.loads(obj))
    except json.JSONDecodeError as e:
        # try to fix trailing comma
        if obj.endswith(','):
            obj = obj[:-1]
        try:
            parsed.append(json.loads(obj))
        except:
            pass
print(f'Successfully parsed {len(parsed)} objects')
if parsed:
    with open('speak_now_tour_partial.json', 'w') as out:
        json.dump(parsed, out, indent=2)
    print('First few dates:')
    for p in parsed[:5]:
        print(p['Date'], p['Host City'])
